<script setup lang="ts">
// 个人研究增强界面：连接数据就绪、用量、提醒、判断日志、组合、实验与项目助手。
import { computed, defineAsyncComponent, nextTick, onActivated, onDeactivated, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { Activity, ArrowLeft, Bell, Check, ChevronLeft, ChevronRight, CircleHelp, FlaskConical, LoaderCircle, MessageSquare, Plus, RefreshCw, Send, ShieldCheck, Square, Trash2 } from 'lucide-vue-next'
import { api, post } from './api'
import ConfirmDialog from './components/ConfirmDialog.vue'
// 按需加载权益及行情图表，复用核心研究界面的图表组件。
const ResearchChart=defineAsyncComponent(()=>import('./components/ResearchChart.vue'))
// 按需加载策略与比较基准的共同区间归一化曲线。
const BenchmarkChart=defineAsyncComponent(()=>import('./components/BenchmarkChart.vue'))
import SourceFacts from './components/SourceFacts.vue'
import AssistantAction from './components/AssistantAction.vue'
import './research.css'

// 接收当前研究页面、登录身份和从报告或证券跳转带入的上下文。
const props = defineProps<{ view: string, user: any, context?: { kind: string, id: string, report_id?: string } | null, assistantPanel?: boolean, showHistory?: boolean, embedded?: boolean }>()
const emit = defineEmits<{ navigate: [name: string], 'clear-context': [] }>()
// 定义研究增强导航，与后端已实现的功能范围对应。
const sections = [ ['readiness','数据就绪度'], ['usage','模型用量'], ['alerts','条件提醒'], ['journals','研究日志'], ['portfolio','组合风险'], ['experiments','历史实验'], ['assistant','AI 助手'] ]
const descriptions: Record<string,string> = { readiness:'先看清数据能支持什么，再开始研究。', usage:'报告、连接测试与项目对话，共用本人的调用上限。', alerts:'用明确条件持续观察，触发记录与通知都有据可查。', journals:'记录当时的判断，用后续交易日与模拟成交分别复核。', portfolio:'以同一账户的现金与有效持仓估值，观察风险敞口。', experiments:'把参数、失败尝试和比较基准一起留在研究课题中。', assistant:'聊聊想法，查询研究结果，准备项目配置与自选方案。' }
const labels: Record<string,string> = { empty:'暂无自选', read_failure:'读取失败', expired:'已到期', active:'启用', disabled:'停用', archived:'已归档', ready:'已就绪', hint:'提示', blocked:'受阻', unknown:'未知', not_applicable:'不适用', incomplete:'资料不完整', verified:'已核验', valid:'有效', queued:'排队中', running:'处理中', validating:'校验中', success:'已完成', failed:'失败', interrupted:'已中断', cancelled:'已停止', uncertain:'结果不确定', help:'项目帮助 · 静态资料', refused:'超出项目范围', clarification:'需要明确对象', permission_required:'需要数据授权', delivered:'已投递', pending_dnd:'免打扰暂存', cooldown:'冷却抑制', resolved:'条件已恢复', not_enabled:'邮件未开启', not_configured:'站点未配置邮件', retry:'等待重试', pending:'等待处理', calendar_unknown:'日历覆盖不足', baseline_missing:'起点价格缺失', pending_start:'等待开盘起点', not_due:'尚未到期', price_missing:'目标价格缺失', suspended:'当日停牌', corporate_actions_unverified:'公司行动未核验', observed:'已计算', closed:'成交已闭合', partial:'部分配对', unlinked:'未关联模拟成交', no_round_trip:'尚无闭合成交', EVIDENCE_OR_DATA_INSUFFICIENT:'历史数据或证据不足', INVALID_OUTPUT:'模型回答未通过结构、引用或事实校验', CONTEXT_TOO_LARGE:'上下文超过预算，请减少所选对象或缩短问题', USAGE_LIMIT:'本人的调用上限已用完', UNCERTAIN_TIMEOUT:'请求可能已送达，未自动重试', SUMMARY_PERMISSION_REQUIRED:'所选模型尚未授权模拟汇总', TRADE_PERMISSION_REQUIRED:'所选模型尚未授权逐笔成交', NO_PROFILE:'请先保存个人默认模型配置', CANCELLED:'请求已停止', SOURCE_DELETED:'来源已删除', OLLAMA_DISABLED:'站点尚未启用服务器 Ollama，可查阅项目帮助或配置其他服务', PROFILE_DISABLED:'所选模型配置已停用', PERMISSION_REVOKED:'数据授权已撤销，请使用当前授权重新提交', RECONNECT_REQUIRED:'恢复后需要重新连接个人凭据', KEY_REVOKED:'模型凭据已撤销', CONSENT_REVOKED:'数据授权已撤销', USAGE_UNAVAILABLE:'用量权威记录不可用，调用已暂停' }
const conditionLabels: Record<string,string> = { price_above:'价格达到或高于', price_below:'价格达到或低于', change_above:'相对参考收盘涨跌幅 ≥', change_below:'相对参考收盘涨跌幅 ≤', risk_changed:'风险状态变化', candidate_invalid:'指定报告候选失效' }
const kindLabels: Record<string,string> = { report:'研究报告', instrument:'证券资料', backtest:'历史回测', account:'模拟账户', experiment:'研究实验' }
// 列表状态与查询条件集中保存，各功能页共享错误、加载和分页反馈。
const busy=ref(false), loading=ref(false), error=ref(''), notice=ref(''), list=ref<any>({items:[],total:0}), page=ref(1), size=ref(20), query=ref(''), status=ref('')
const watchlist=ref<any[]>([]), reports=ref<any[]>([]), profiles=ref<any[]>([]), accounts=ref<any[]>([]), backtests=ref<any[]>([]), topics=ref<any[]>([])
const readiness=ref<any>(null), usage=ref<any>(null), limits=ref<any>({daily:null,monthly:null,version:0}), notification=ref<any>(null), events=ref<any>(null), risk=ref<any>(null), selectedAccount=ref('')
// 编辑草稿与已保存详情分别管理，跨功能页切换时按页面暂存草稿。
const editor=ref<any>(null), editorOpen=ref(true), editorDrafts:Record<string,any>={}, journal=ref<any>(null), experiment=ref<any>(null), comparison=ref<any>(null), selectedExperiments=ref<string[]>([]), topicFilter=ref(''), topicName=ref(''), topicQuestion=ref('')
// 助手会话、待发送问题、对象引用和消息分页独立管理。
const session=ref<any>(null), sessions=ref<any>({items:[],total:0}), question=ref(''), contexts=ref<{kind:string,id:string}[]>([]), contextKind=ref('report'), contextId=ref(''), profileId=ref(''), help=ref<any>(null), sendKey=ref(''), sessionPage=ref(1), messagePage=ref(1)
const confirmText=ref(''), leavePrompt=ref(false),sendFingerprint=ref('')
const editorForm=ref<HTMLElement|null>(null),leaveForm=ref<HTMLElement|null>(null)
const settingsDirty=ref<Record<string,boolean>>({})
let activated=true,initialized=false
let resolveConfirm: ((v:boolean)=>void)|null=null, resolveLeave:((v:boolean)=>void)|null=null, poll:ReturnType<typeof setInterval>, generation=0
// 统一格式化状态、数值、百分比、北京时间，并提供随机客户端幂等键。
const shanghaiDateTime=(value:string)=>value?new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)).replace(' ','T'):''
const label=(s:any)=>labels[s] || s || '—', fmt=(v:any,d=2)=>v===null||v===undefined?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d}), pct=(v:any)=>v===null||v===undefined?'—':fmt(v)+'%', dt=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—', key=()=>crypto.randomUUID()
// 检测未提交的编辑器、问题和研究主题内容，供离开确认使用。
const dirty=computed(()=>!!editor.value || (props.view==='assistant'&&!!question.value.trim()) || (props.view==='experiments'&&(!!topicName.value.trim()||!!topicQuestion.value.trim())) || !!settingsDirty.value[props.view])
// 从当前会话中找到尚未完成的消息，供轮询与停止操作使用。
const pending=computed(()=>session.value?.messages?.find((m:any)=>['queued','running','validating'].includes(m.status)))
// 按上下文类型生成本人可选择的证券、报告、账户或实验列表。
const contextOptions=computed(()=>contextKind.value==='instrument'?watchlist.value.map((w:any)=>({id:w.id,title:w.name+' · '+w.id})):contextKind.value==='report'?reports.value.map((r:any)=>({id:r.id,title:r.report_date+' · 版本'+r.version+' · '+(r.summary||r.mode)})):contextKind.value==='account'?accounts.value.map((a:any)=>({id:a.id,title:a.name})):contextKind.value==='backtest'?backtests.value.map((b:any)=>({id:b.id,title:'历史回测 · '+dt(b.created_at)})):list.value.items.filter((r:any)=>r.parameters).map((r:any)=>({id:r.id,title:r.parameters.instrument_id+' · '+label(r.status)+' · '+dt(r.created_at)})))
// 根据当前功能页标识派生中文标题。
const title=computed(()=>sections.find(s=>s[0]===props.view)?.[1])
// 打开共享确认弹窗，并把用户选择转换为可等待结果。
function confirm(message:string){confirmText.value=message;return new Promise<boolean>(r=>resolveConfirm=r)}
// 关闭确认框并释放等待中的回调。
function settle(v:boolean){confirmText.value='';resolveConfirm?.(v);resolveConfirm=null}
// 存在未保存内容时先等待离开选择，再允许外层切换页面。
async function guard(){if(!dirty.value)return true;leavePrompt.value=true;return new Promise<boolean>(r=>resolveLeave=r)}
// 按用户选择保留或清空草稿，并结束离开确认。
function leave(keep:boolean){leavePrompt.value=false;if(!keep){editor.value=null;question.value='';topicName.value='';topicQuestion.value='';settingsDirty.value[props.view]=false}resolveLeave?.(true);resolveLeave=null}
// 向外层公开离开保护，确保管理页导航也能处理未保存内容。
const messageVersion=computed(()=>session.value?.messages?.map((m:any)=>m.id+':'+m.status).join('|')||'')
const sessionId=computed(()=>session.value?.id||'')
const selectedProfile=computed(()=>profiles.value.find((p:any)=>profileId.value?p.id===profileId.value:p.is_default))
function contextTitle(c:{kind:string,id:string}){const report=reports.value.find((r:any)=>r.id===c.id);return c.kind==='report'&&report?report.report_date+' · 版本 '+report.version+' · '+c.id.slice(0,8):c.kind==='instrument'?(watchlist.value.find((w:any)=>w.id===c.id)?.name||'')+' '+c.id:c.id}
function focusQuestion(){document.getElementById('assistant-question')?.focus()}
defineExpose({guard,dirty,pending,messageVersion,sessionId,newSession,focusQuestion,reload})
// 浏览器关闭或刷新且存在草稿时触发原生离开提醒。
function unload(e:BeforeUnloadEvent){if(dirty.value||Object.values(editorDrafts).some(Boolean)||Object.values(settingsDirty.value).some(Boolean)||question.value.trim()){e.preventDefault();e.returnValue=''}}
// 串行处理提交动作，版本冲突时保留草稿并显示重新读取提示。
async function action(fn:()=>Promise<any>,message=''){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const r=await fn();if(message)notice.value=message;return r}catch(e:any){error.value=e.code==='VERSION_CONFLICT'?'已有新版本。草稿已保留，请重新载入记录后再保存。':e.message;return null}finally{busy.value=false}}
// 读取本人研究对象的精简选项，供提醒、判断和助手引用表单使用。
async function common(){const r=await api('/me/research/options');watchlist.value=r.watchlist;reports.value=r.reports;profiles.value=r.profiles;accounts.value=r.accounts;backtests.value=r.backtests}
// 重新读取本人对象选项和当前页面，再应用一次性跳转上下文，并统一处理加载错误。
async function reload(){loading.value=true;try{await common();await refresh();contextFromRoute()}catch(e:any){error.value=e.message}finally{loading.value=false}}
// 将 Tab 和 Shift+Tab 的焦点限制在当前弹窗的可操作元素之间。
function trap(e:KeyboardEvent){const root=e.currentTarget as HTMLElement;const elements=Array.from(root.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]'));const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
// 冻结本次请求参数，并在每次异步读取后核对代次，避免旧页面或筛选结果覆盖当前视图。
async function refresh(){const token=++generation,view=props.view,topic=topicFilter.value,sessionQuery=new URLSearchParams({page:String(sessionPage.value),size:String(size.value),q:query.value}),hash=location.hash;const current=()=>alive&&token===generation&&props.view===view;loading.value=true;error.value='';try{
  const params=new URLSearchParams({page:String(page.value),size:String(size.value),q:query.value,status:status.value})
  if(view==='readiness'){const value=await api('/me/readiness?'+params);if(current())readiness.value=value}
  else if(view==='usage'){const value=await api('/me/usage');if(!current())return;usage.value=value;if(!settingsDirty.value.usage)limits.value={...value.settings}}
  else if(view==='alerts'){const r=await Promise.all([api('/me/alerts?'+params),api('/me/alerts/events?'+params),api('/me/alerts/settings')]);if(!current())return;list.value=r[0];events.value=r[1];if(!settingsDirty.value.alerts)notification.value=r[2]}
  else if(view==='journals'){const value=await api('/me/journals?'+params);if(current())list.value=value}
  else if(view==='portfolio'){if(!selectedAccount.value)selectedAccount.value=accounts.value[0]?.id||'';const account=selectedAccount.value;const value=account?await api('/me/portfolio/'+account+'/risk'):null;if(current())risk.value=value}
  else if(view==='experiments'){const nextTopics=await api('/me/experiment-topics?size=50');if(!current())return;const value=await api('/me/experiments?'+params+'&topic_id='+encodeURIComponent(topic));if(!current())return;topics.value=nextTopics.items;list.value=value}
  else if(view==='assistant'){const nextSessions=await api('/me/assistant/sessions?'+sessionQuery);if(!current())return;const nextHelp=await api('/me/assistant/help');if(!current())return;const requested=hash.split('?')[0]==='#assistant'?new URLSearchParams(hash.split('?')[1]).get('session'):null;sessions.value=nextSessions;help.value=nextHelp;if(requested&&session.value?.id!==requested){session.value=null;messagePage.value=1;await openSession(requested,current)}else if(!session.value&&nextSessions.items[0])await openSession(nextSessions.items[0].id,current);if(!current())return;const value=await api('/me/experiments?size=50');if(current())list.value=value}
}catch(e:any){if(current())error.value=e.message}finally{if(current())loading.value=false}}
// 更新筛选条件后回到第一页再请求数据。
function filter(){page.value=1;void refresh()}
// 按翻页方向调整页码，并重新加载当前筛选结果。
async function changePage(delta:number){page.value+=delta;await refresh()}
// 合并外层或哈希带入的对象，按页面初始化判断或账户选择后清除一次性上下文。
function contextFromRoute(){const p=new URLSearchParams(location.hash.split('?')[1]);const c=props.context||(p.get('kind')&&p.get('id')?{kind:p.get('kind')!,id:p.get('id')!}:null);if(c&&Object.keys(kindLabels).includes(c.kind)&&!contexts.value.some(x=>x.kind===c.kind&&x.id===c.id)){if(contexts.value.length<5){contexts.value.push(c);if(props.view==='assistant')notice.value='已附带'+kindLabels[c.kind]+' · '+c.id+'，仅用于下一次明确发送的问题。'}else notice.value='最多附带五项资料，请先移除不需要的对象。'}if(c&&props.view==='journals')newJournal(c.kind==='instrument'?c.id:'',c.kind==='report'?c.id:(c.report_id||''));if(c&&props.view==='portfolio'&&c.kind==='account'){selectedAccount.value=c.id;void refresh()}if(props.view==='assistant'&&p.get('help')){const entry=help.value?.entries.find((e:any)=>e.id===p.get('help'));if(p.get('version')&&p.get('version')!==help.value?.version)notice.value='所请求的旧版帮助未在当前知识库中提供，请查看原会话存档引用。';else if(entry)notice.value=entry.title+'：'+entry.text}if(props.view==='experiments'&&p.get('experiment')&&experiment.value?.id!==p.get('experiment'))void openExperiment(p.get('experiment')!);if(props.view==='portfolio'&&p.get('account')&&selectedAccount.value!==p.get('account')){selectedAccount.value=p.get('account')!;void refresh()}emit('clear-context')}
// 复制可编辑的提醒字段或创建默认草稿，并生成本次提交的幂等键。
function newAlert(row:any=null){if(editor.value){editorOpen.value=true;notice.value='已有未保存草稿，请先保存或放弃。';return}editorOpen.value=true;editor.value={kind:'alert',id:row?.id,version:row?.version,client_key:key(),reference:row?.data.reference,data:row?Object.fromEntries(['name','instrument_id','condition','threshold','report_id','cooldown_minutes','expires_at','dnd_start','dnd_end','email','enabled'].map(k=>[k,row.data[k]])):{name:'',instrument_id:watchlist.value[0]?.id||'',condition:'price_above',threshold:null,report_id:null,cooldown_minutes:60,expires_at:new Date(Date.now()+30*86400000).toISOString(),dnd_start:null,dnd_end:null,email:false,enabled:true}}}
// 规范化不适用的阈值与空字段，可只预览条件，也可按版本保存提醒。
async function saveAlert(preview=false){await action(async()=>{const e=editor.value;const payload={...e.data,threshold:['risk_changed','candidate_invalid'].includes(e.data.condition)?null:e.data.threshold,dnd_start:e.data.dnd_start||null,dnd_end:e.data.dnd_end||null,report_id:e.data.report_id||null};if(preview){const r=await post('/me/alerts/preview'+(e.id?'?rule_id='+encodeURIComponent(e.id)+'&version='+e.version:''),payload);notice.value='条件预览：'+label(r.current.quality)+'；当前值 '+fmt(r.current.value)+'；'+(r.current.satisfied===null?'无法判断':r.current.satisfied?'已满足':'未满足')+(r.condition.reference?'；冻结参考收盘 '+fmt(r.condition.reference.close)+' · '+dt(r.condition.reference.ts):'');return}await api('/me/alerts'+(e.id?'/'+e.id:''),{method:e.id?'PUT':'POST',body:JSON.stringify({data:payload,version:e.version,client_key:e.client_key})});editor.value=null;await refresh()},preview?'':'提醒已保存，站点将按新版本评估。')}
// 从证券或报告初始化判断草稿，编辑已有记录时保留归属与版本。
async function newJournal(instrumentId='',reportId='',row:any=null){if(editor.value){editorOpen.value=true;notice.value='已有未保存草稿，请先保存或放弃。';return}editorOpen.value=true;journal.value=null;editor.value={kind:'journal',id:row?.id,version:row?.version,client_key:key(),data:row?Object.fromEntries(['instrument_id','report_id','rationale','counterargument','invalidation','note','order_ids'].map(k=>[k,row.data[k]])):{instrument_id:instrumentId||watchlist.value[0]?.id||'',report_id:reportId||null,rationale:'',counterargument:'',invalidation:'',note:'',order_ids:[]}};if(reportId&&!instrumentId){try{const report=await api('/me/reports/'+reportId);const first=report.candidates?.[0]||report.excluded?.[0];if(first)editor.value.data.instrument_id=first.instrument_id}catch(e:any){error.value=e.message}}}
// 保存判断的新修订，判断时点由服务端记录而不使用浏览器时间。
async function saveJournal(){await action(async()=>{const e=editor.value;const data={...e.data,report_id:e.data.report_id||null};await api('/me/journals'+(e.id?'/'+e.id:''),{method:e.id?'PUT':'POST',body:JSON.stringify({data,version:e.version,client_key:e.client_key})});editor.value=null;await refresh()},'判断已保存为新版本，后续观察使用服务器记录时间。')}
// 读取本人判断各版内容和后续观察结果。
async function openJournal(id:string){await action(async()=>journal.value=await api('/me/journals/'+id))}
// 确认后删除提醒、日志或会话，清理当前详情并重新读取列表。
async function remove(kind:string,row:any){if(!await confirm('删除这条'+(kind==='alerts'?'提醒':kind==='journals'?'研究日志':'对话')+'及其私人记录？删除后无法恢复。'))return;await action(async()=>{await api('/me/'+kind+'/'+row.id,{method:'DELETE'});if(kind==='journals')journal.value=null;if(kind==='assistant/sessions')session.value=null;await refresh()},'已删除，旧备份恢复时也会应用删除记录。')}
// 按当前版本归档或恢复判断，保留原始修订记录。
async function archive(row:any){await action(async()=>{await post('/me/journals/'+row.id+'/archive',{version:row.version,archived:row.status!=='archived'});journal.value=null;await refresh()},'日志归档状态已更新。')}
// 创建新的研究课题，成功后将实验列表筛选到该课题。
async function createTopic(){await action(async()=>{const r=await post('/me/experiment-topics',{name:topicName.value,question:topicQuestion.value,client_key:key()});topicName.value='';topicQuestion.value='';topicFilter.value=r.id;await refresh()},'研究课题已创建。')}
// 从默认参数或父实验复制实验草稿，保留可追溯的父子关系。
function newExperiment(parent:any=null){if(editor.value){editorOpen.value=true;notice.value='已有未保存草稿，请先保存或放弃。';return}editorOpen.value=true;editor.value={kind:'experiment',client_key:key(),topic_id:parent?.topic_id||topicFilter.value||topics.value[0]?.id||'',index_id:null,parent_id:parent?.id||null,parameters:parent?{...parent.parameters}:{instrument_id:watchlist.value[0]?.id||'',initial_cash:10000,fast:5,slow:20,train_ratio:0.7,stop_loss_pct:0.05,strict:true,start_date:'',end_date:''}}}
// 清理空日期并确认非严格模式后提交队列，实际开始才计算尝试次数。
async function saveExperiment(){await action(async()=>{const e=editor.value;const parameters={...e.parameters};if(!parameters.start_date)delete parameters.start_date;if(!parameters.end_date)delete parameters.end_date;if(!parameters.strict&&!await confirm('缺少历史状态或公司行动证据时，结果可能失真。以未验证实验继续？'))return;await post('/me/experiments',{client_key:e.client_key,topic_id:e.topic_id,index_id:e.index_id||null,parent_id:e.parent_id||null,parameters});editor.value=null;await refresh()},'实验已排队。实际开始后才计入课题尝试次数。')}
// 读取本人指定实验的参数、状态、策略结果与比较基准。
async function openExperiment(id:string){await action(async()=>experiment.value=await api('/me/experiments/'+id))}
// 提交已选本人实验，展示口径差异而不自行推断优胜策略。
async function compare(){await action(async()=>comparison.value=await post('/me/experiments/compare',{ids:selectedExperiments.value}))}
// 创建个人助手会话，选中该会话并刷新索引。
async function newSession(){await action(async()=>{const r=await post('/me/assistant/sessions',{title:'新对话',client_key:key()});await chooseSession(r.id);await refresh();focusQuestion()})}
// 按消息页码读取会话与已检查的回复，支持重新进入后续读。
let sessionRead=0,alive=true
async function openSession(id:string,current:()=>boolean=()=>true){const token=++sessionRead;const value=await api('/me/assistant/sessions/'+encodeURIComponent(id)+'?page='+messagePage.value+'&size='+size.value);if(alive&&token===sessionRead&&current())session.value=value}
async function chooseSession(id:string){messagePage.value=1;if(location.hash.split('?')[0]==='#assistant')history.replaceState(null,'','#assistant?session='+encodeURIComponent(id));await openSession(id)}
// 限制上下文最多五个且不重复，添加完成后清空当前选择。
function addContext(){if(contextId.value&&contexts.value.length<5&&!contexts.value.some(c=>c.kind===contextKind.value&&c.id===contextId.value))contexts.value.push({kind:contextKind.value,id:contextId.value});contextId.value=''}
// 复用本次问题的幂等键，提交指定模型与对象，成功后刷新消息并等待后台处理。
async function send(regenerate:any=null){if(!regenerate&&(!question.value.trim()||Array.from(question.value).length>4000))return;await action(async()=>{if(!session.value){const s=await post('/me/assistant/sessions',{title:question.value.slice(0,40)||'新对话',client_key:key()});await chooseSession(s.id)}const fingerprint=JSON.stringify({session:session.value.id,question:regenerate?regenerate.question:question.value,contexts:regenerate?regenerate.context.contexts:contexts.value,profile:profileId.value,regenerate:regenerate?.id});if(!sendKey.value||sendFingerprint.value!==fingerprint){sendKey.value=key();sendFingerprint.value=fingerprint}const r=await post('/me/assistant/sessions/'+session.value.id+'/messages',{client_key:sendKey.value,question:regenerate?regenerate.question:question.value,contexts:regenerate?regenerate.context.contexts:contexts.value,profile_id:profileId.value||null,regenerate_of:regenerate?.id||null});question.value='';sendKey.value='';messagePage.value=1;await openSession(session.value.id);sessions.value=await api('/me/assistant/sessions?page=1&size='+size.value);if(r.status==='queued')notice.value='已加入个人队列。可离开页面，回来后继续读取这次回答。'})}
// 等待服务端确认停止，再刷新消息；已经发送的供应商用量仍可能计入额度。
async function stopMessage(m:any){await action(async()=>{await post('/me/assistant/requests/'+m.id+'/stop');await openSession(session.value.id)},'已确认停止。已发出的调用仍可能占用一次额度。')}
// 仅在本人点击已展示方案的应用按钮时提交；模型响应和轮询不会触发写入。
async function applyAssistantAction(message:any,index:number){await action(async()=>{await post('/me/assistant/requests/'+encodeURIComponent(message.id)+'/actions/'+index+'/apply',{confirm:true});await openSession(session.value.id);await common()},'方案已由你手动应用。')}
// 检查未保存内容后，以指定对象作为助手问题上下文。
async function askAbout(kind:string,id:string){if(!await guard())return;emit('navigate','assistant?kind='+encodeURIComponent(kind)+'&id='+encodeURIComponent(id))}
// 将已核验来源卡跳转到对应研究对象，项目帮助则直接显示版本化正文。
function sourceLink(ref:any){if(ref.kind==='help'||ref.id?.startsWith('help:')){if(typeof ref.facts==='string'){notice.value=(ref.title||'项目帮助')+' · '+(ref.version||'归档版本')+'：'+ref.facts;return}if(ref.version&&ref.version!==help.value?.version){notice.value='这份旧版帮助正文未保留，请从原会话查看可用归档；不会用当前说明替换旧版。';return}const e=help.value?.entries.find((r:any)=>'help:'+r.id===ref.id);if(e)notice.value=e.title+'：'+e.text;return}if(ref.kind==='preferences'){emit('navigate','preferences');return}if(ref.kind==='report'){emit('navigate','reports?report='+ref.object_id);return}if(ref.kind==='instrument'){emit('navigate','watchlist?instrument='+ref.object_id);return}if(ref.kind==='account'){emit('navigate','portfolio?account='+encodeURIComponent(ref.object_id));return}if(ref.kind==='comparison'){emit('navigate','reports');return}if(ref.kind==='backtest'){emit('navigate','review?backtest='+ref.object_id);return}if(ref.kind==='experiment'){emit('navigate','experiments?experiment='+encodeURIComponent(ref.object_id))}}
// 将服务端事实转换为纯文本，由模板插值展示而不执行 HTML。
function safeFacts(value:any):string{if(typeof value==='string')return value;return JSON.stringify(value,null,2)}
// 切换功能时缓存当前草稿，重置列表筛选并加载新页面及一次性上下文。
watch(()=>props.view,async(next,previous)=>{editorDrafts[previous]=editor.value;editor.value=editorDrafts[next]||null;editorOpen.value=false;list.value={items:[],total:0};page.value=1;query.value='';status.value='';error.value='';notice.value='';await reload()})
// 从其他页面再次带入研究对象时更新当前上下文。
watch(()=>props.context,contextFromRoute)
function assistantHash(){if(props.view!=='assistant'||location.hash.split('?')[0]!=='#assistant')return;contextFromRoute();const id=new URLSearchParams(location.hash.split('?')[1]).get('session');if(id&&session.value?.id!==id){session.value=null;messagePage.value=1;void openSession(id).catch((e:any)=>error.value=e.message)}}
// 问题文本改变即生成新的提交身份，网络重试期间则复用原幂等键。
// 问题文本改变时清空旧幂等键，再次发送时生成新的请求标识。
watch(question,()=>{sendKey.value=''})
watch(editor,value=>{editorDrafts[props.view]=value})
// 挂载后加载选项与当前页，仅在页面可见且没有提交操作时轮询进行中的任务。
watch([editor,editorOpen],async()=>{if(editor.value&&editorOpen.value){await nextTick();editorForm.value?.querySelector<HTMLElement>('input,select,textarea')?.focus()}})
watch(leavePrompt,async value=>{if(value){await nextTick();leaveForm.value?.querySelector<HTMLElement>('button')?.focus()}})
onMounted(async()=>{window.addEventListener('beforeunload',unload);window.addEventListener('hashchange',assistantHash);await reload();initialized=true;poll=setInterval(async()=>{if(!activated||document.hidden||busy.value)return;try{if(props.view==='assistant'&&pending.value&&session.value)await openSession(session.value.id);if(props.view==='experiments'&&list.value.items.some((r:any)=>['queued','running'].includes(r.status)))await refresh()}catch(e:any){error.value=e.message}},1500)})
onActivated(()=>{activated=true;if(initialized)void reload()})
onDeactivated(()=>{activated=false})
// 卸载时停止轮询与离开监听，完成待处理的确认以免回调悬空。
onBeforeUnmount(()=>{alive=false;sessionRead++;clearInterval(poll);window.removeEventListener('beforeunload',unload);window.removeEventListener('hashchange',assistantHash);settle(false);resolveLeave?.(false)})
</script>

<template>
<!-- 增强工作台按功能分区展示，所有事实来自本人可访问的服务端对象。 -->
  <div :class="['research-shell', {'research-embedded':embedded}]">
    <aside v-if="!assistantPanel&&!embedded" class="research-nav"><div class="research-nav-heading"><span class="eyebrow">RESEARCH DESK</span><strong>把研究连起来</strong></div><nav aria-label="研究增强功能"><button @click="emit('navigate','dashboard')"><ArrowLeft :size="17"/>研究总览</button><button @click="emit('navigate','jobs')"><Activity :size="17"/>任务中心</button><button v-for="s in sections" :key="s[0]" :class="{active:view===s[0]}" @click="emit('navigate',s[0]!)"><Bell v-if="s[0]==='alerts'" :size="17"/><MessageSquare v-else-if="s[0]==='assistant'" :size="17"/><FlaskConical v-else-if="s[0]==='experiments'" :size="17"/><ShieldCheck v-else-if="s[0]==='readiness'" :size="17"/><Activity v-else :size="17"/>{{s[1]}}</button></nav><p>私人记录归本人所有<br/>Asia/Shanghai · 仅供研究与模拟</p><button class="text-button" @click="emit('navigate','dashboard')"><ArrowLeft :size="14"/>返回研究总览</button></aside>
    <main class="research-main">
      <div v-if="!assistantPanel" class="page-heading"><div><div class="eyebrow">YOUR RESEARCH, CONNECTED</div><h1>{{title}}</h1><p>{{descriptions[view]}}</p></div><button class="secondary small" :disabled="loading||busy" @click="refresh"><RefreshCw :size="14" :class="{spin:loading}"/>刷新</button></div>
      <div v-if="editor&&!editorOpen" class="public-message">有未保存草稿。<button class="text-button" @click="editorOpen=true">继续编辑</button></div><div v-if="error" role="alert" class="public-message error">{{error}}<button class="text-button" @click="refresh">重试读取</button></div><div v-if="notice" role="status" class="public-message research-notice">{{notice}}<button class="text-button" @click="notice=''" aria-label="关闭提示">收起</button></div>
      <div v-if="loading&&!readiness&&!usage&&!list.items.length" class="research-loading"><LoaderCircle class="spin" :size="20"/>正在读取本人资料</div>

      <template v-if="view==='readiness'&&readiness">
        <div class="research-metrics"><article class="panel"><small>当前就绪状态</small><strong>{{error?'读取失败':label(readiness.status)}}</strong><span>计算 {{dt(readiness.calculated_at)}}</span></article><article class="panel"><small>受影响证券 / 全部自选</small><strong>{{readiness.affected_objects}} <em>/ {{readiness.object_count}}</em></strong><span>同一证券只计一次</span></article><article class="panel"><small>待处理原因</small><strong>{{readiness.issue_count}}</strong><span>原因可同时影响同一证券</span></article></div>
        <section class="panel research-section"><div class="panel-heading"><div><h2>从阻断原因开始</h2><p>当前刷新只读取已存数据，不发起外部采集；归档报告使用生成时的事实。</p></div><ShieldCheck :size="20"/></div><form class="research-filters" @submit.prevent="filter"><label>证券或原因<input v-model="query" placeholder="搜索证券、代码或原因"/></label><label>状态<select v-model="status" @change="filter"><option value="">全部状态</option><option v-for="s in ['blocked','unknown','hint','not_applicable']" :value="s">{{label(s)}}</option></select></label><button class="secondary">筛选</button></form><div v-if="!readiness.issues.length" class="research-empty"><Check :size="24"/><h3>{{readiness.object_count?'当前筛选没有问题记录':'还没有个人自选'}}</h3><p>{{readiness.object_count?'可切换筛选查看其他状态。':'加入自选后，可查看候选筛选、严格回测和行情观察的就绪情况。'}}</p><button class="secondary" @click="emit('navigate','watchlist')">前往自选</button></div><article v-for="r in readiness.issues" :key="r.instrument_id+r.code" class="readiness-row"><div><b>{{r.name}}</b><small>{{r.instrument_id}}</small></div><div><span :class="['tag',r.status==='blocked'?'amber':'']">{{label(r.status)}}</span><strong>{{r.message}}</strong><small>{{{candidate:'候选筛选',strict_backtest:'严格回测',market:'行情观察'}[r.task as string]}} · {{r.code}} · {{r.rule_version}}</small><small>报价 {{dt(r.quote_time)}} · 采集 {{dt(r.collected_at)}} · 核验 {{dt(r.verified_at)}}</small><a v-if="r.source_url" :href="r.source_url" target="_blank" rel="noopener noreferrer">查看原始来源</a></div><button class="secondary small" @click="emit('navigate','watchlist?instrument='+r.instrument_id)">{{r.action.admin_required&&user.role!=='admin'?'查看资料 · 需管理员维护':'查看并处理'}}</button></article><details class="readiness-abilities"><summary>查看证券对各项能力的就绪状态（前 {{size}} 只）</summary><div class="table-scroll"><table class="watch-table"><thead><tr><th>证券</th><th>候选筛选</th><th>严格回测</th><th>行情观察</th></tr></thead><tbody><tr v-for="o in readiness.objects.slice(0,size)" :key="o.instrument_id"><td>{{o.name}}<small>{{o.instrument_id}}</small></td><td>{{label(o.abilities?.candidate)}}</td><td>{{label(o.abilities?.strict_backtest)}}</td><td>{{label(o.abilities?.market)}}</td></tr></tbody></table></div></details><p class="research-footnote">{{readiness.calendar.note}} · 规则 {{readiness.rule_version}}</p></section>
        <section v-if="readiness.latest_report" class="panel research-section"><h2>最近归档的实际筛选池</h2><p>版本 {{readiness.latest_report.version}} · {{readiness.latest_report.report_date}} · {{readiness.latest_report.candidate_count}} 只候选</p><p v-if="!readiness.latest_report.candidate_count">该次报告没有合格模拟候选；以下是当时的排除记录。</p><p v-for="r in readiness.latest_report.excluded" :key="r.instrument_id"><b>{{r.name||r.instrument_id}}</b> · {{r.reasons.join('；')}}</p><button class="text-button" @click="emit('navigate','reports?report='+readiness.latest_report.id)">查看归档报告</button></section>
      </template>

      <template v-if="view==='usage'&&usage">
        <div class="research-metrics"><article v-for="period in ['daily','monthly']" :key="period" class="panel"><small>{{period==='daily'?'今日调用':'本月调用'}} · {{usage[period].window}}</small><strong>{{usage[period].sent}} <em>/ {{usage[period].limit??'未设上限'}}</em></strong><span>预留 {{usage[period].reserved}} · 其中不确定 {{usage[period].uncertain}}</span><span>剩余 {{usage[period].remaining??'未限制'}} · 已知 Token {{fmt(usage[period].known_tokens,0)}}</span></article><article class="panel"><small>服务商余额与账单金额</small><strong>未提供</strong><span>未知用量 {{usage.monthly.unknown_usage}} 次</span><span>缺少 usage 的调用仍计入次数</span></article></div>
        <form class="panel research-section" @input="settingsDirty.usage=true" @submit.prevent="action(async()=>{usage=await api('/me/usage/limits',{method:'PUT',body:JSON.stringify(limits)});limits={...usage.settings};settingsDirty.usage=false},'本人调用上限已更新，发出请求前会重新核对。')"><div class="panel-heading"><div><h2>本人的调用上限</h2><p>留空表示未设置，0 表示暂停该窗口内的全部模型调用。</p></div></div><div class="form-grid"><label>每日最多调用次数<input v-model="limits.daily" type="number" min="0" step="1" placeholder="未设置" @change="limits.daily=limits.daily===''?null:Number(limits.daily)"/></label><label>每月最多调用次数<input v-model="limits.monthly" type="number" min="0" step="1" placeholder="未设置" @change="limits.monthly=limits.monthly===''?null:Number(limits.monthly)"/></label></div><p class="research-footnote">按服务器上海时间计算。规则报告降级不消耗模型次数；请求发出后的失败和不确定结果占一次，重试另计一次。</p><button class="primary" :disabled="busy">保存上限</button></form>
        <section class="panel research-section"><h2>本月调用分布</h2><div class="table-scroll"><table class="watch-table"><thead><tr><th>个人配置</th><th>用途</th><th>已发出</th><th>有效预留</th><th>已知 Token</th><th>未知 usage</th></tr></thead><tbody><tr v-for="g in usage.groups" :key="g.profile_id+g.purpose"><td>{{profiles.find(p=>p.id===g.profile_id)?.name||'历史配置'}}</td><td>{{{assistant:'项目对话',profile_test:'连接测试',standard:'标准早报',closing:'收盘跟踪',full:'深度复盘',supplement:'补充AI'}[g.purpose as string]||g.purpose}}</td><td>{{g.sent}}</td><td>{{g.reserved}}</td><td>{{fmt(g.known_tokens,0)}}</td><td>{{g.unknown_usage}}</td></tr></tbody></table></div><p v-if="!usage.groups.length" class="research-empty">本月暂无已发送或预留的模型请求。</p></section>
      </template>

      <template v-if="view==='alerts'">
        <!-- 条件提醒：分别展示规则版本、评估证据、触发事件与渠道投递状态。 -->
        <section class="panel research-section"><div class="panel-heading"><div><h2>我的条件规则</h2><p>默认冷却 60 分钟、有效期 30 天；同一条件持续满足不会重复触发。</p></div><button class="primary small" @click="newAlert()"><Plus :size="15"/>新增提醒</button></div><form class="research-filters" @submit.prevent="filter"><label>搜索<input v-model="query" placeholder="名称或代码"/></label><label>状态<select v-model="status" @change="filter"><option value="">全部</option><option value="active">启用</option><option value="disabled">停用</option><option value="expired">已到期</option></select></label><button class="secondary">筛选</button></form><div v-if="!list.items.length" class="research-empty"><Bell :size="30"/><h3>为关注的变化设一个条件</h3><p>提醒只使用已保存的行情与规则，不调用模型。</p><button class="secondary" @click="newAlert()">创建第一条提醒</button></div><article v-for="r in list.items" :key="r.id" class="research-list-row"><div><b>{{r.data.name}}</b><small>{{r.data.instrument_id}} · {{conditionLabels[r.data.condition]}} {{r.data.threshold??''}} · 版本 {{r.version}}</small><small>{{r.data.pause_reason?'恢复后待本人复核，需重新启用；':''}}当前 {{label(r.evaluation?.quality||'unknown')}} · 上次评估 {{dt(r.evaluation?.last_evaluated)}} · {{r.data.expires_at?'有效至 '+dt(r.data.expires_at):'持续有效'}}</small></div><small v-if="r.data.reference" class="research-footnote">参考收盘 {{fmt(r.data.reference.close)}} · {{dt(r.data.reference.ts)}}</small><span :class="['tag',r.status==='active'?'green':'']">{{label(r.status)}}</span><div class="button-row"><button class="secondary small" @click="newAlert(r)">编辑</button><button v-if="r.status==='expired'" class="text-button" @click="newAlert(r)">更新有效期</button><button v-else class="text-button" @click="action(async()=>{const data:any=Object.fromEntries(['name','instrument_id','condition','threshold','report_id','cooldown_minutes','expires_at','dnd_start','dnd_end','email','enabled'].map(k=>[k,r.data[k]]));data.enabled=r.status!=='active';delete data.currency;delete data.unit;delete data.rule_version;delete data.reference;delete data.report_version;delete data.input_fingerprint;delete data.pause_reason;await api('/me/alerts/'+r.id,{method:'PUT',body:JSON.stringify({version:r.version,data})});await refresh()})">{{r.status==='active'?'停用':'启用'}}</button><button class="icon-button" :aria-label="'删除提醒'+r.data.name" @click="remove('alerts',r)"><Trash2 :size="15"/></button></div></article></section>
        <section v-if="notification" class="panel research-section"><div class="panel-heading"><div><h2>通知渠道</h2><p>站内通知默认开启。邮件还需每条规则开启、本人开启及站点配置就绪。</p></div></div><label class="check-label"><input v-model="notification.email_enabled" type="checkbox" @change="settingsDirty.alerts=true"/>允许向本人的已验证邮箱发送提醒</label><p class="research-footnote">站点邮件：{{notification.smtp_configured?'已配置':'尚未配置，站内提醒仍可使用'}}</p><button class="secondary small" :disabled="busy" @click="action(async()=>{notification=await api('/me/alerts/settings',{method:'PUT',body:JSON.stringify({version:notification.version,email_enabled:notification.email_enabled})});settingsDirty.alerts=false},'通知设置已保存。')">保存渠道设置</button></section>
        <section v-if="events" class="panel research-section"><h2>触发与投递记录</h2><p v-if="!events.items.length" class="research-empty">暂无触发事件。资料缺失时会保留未知，不当作条件恢复。</p><details v-for="e in events.items" :key="e.id" class="research-event"><summary><span>{{e.facts.name}} · {{conditionLabels[e.facts.condition]}}</span><span class="tag">{{label(e.state)}}</span><small>{{dt(e.triggered_at)}}</small></summary><p>值 {{fmt(e.facts.value)}} / 阈值 {{fmt(e.facts.threshold)}} {{e.facts.currency}} · 报价 {{dt(e.facts.quote_time)}} · {{e.facts.rule_version}}</p><p>{{e.facts.reasons?.join('；')}}</p><a v-if="e.facts.source_url" :href="e.facts.source_url" target="_blank" rel="noopener noreferrer">原始来源</a><small v-for="d in events.deliveries.filter((d:any)=>JSON.parse(d.event_ids_json).includes(e.id))" :key="d.id">{{d.channel==='email'?'邮件':'站内'}} · {{label(d.state)}} · {{d.error_code||''}}</small></details></section>
      </template>

      <template v-if="view==='journals'">
        <!-- 研究日志：保留每版判断，并区分后续价格观察与实际模拟成交收益。 -->
        <section v-if="!journal" class="panel research-section"><div class="panel-heading"><div><h2>把判断留在当时</h2><p>记录不会自动发送给模型。修改判断会追加修订，历史内容保持可查。</p></div><button class="primary small" @click="newJournal()"><Plus :size="15"/>新增研究日志</button></div><form class="research-filters" @submit.prevent="filter"><label>搜索<input v-model="query" placeholder="证券、判断或备注"/></label><label>状态<select v-model="status" @change="filter"><option value="">全部</option><option value="active">研究中</option><option value="archived">已归档</option></select></label><button class="secondary">筛选</button></form><div v-if="!list.items.length" class="research-empty"><h3>留下第一条研究判断</h3><p>可从证券或报告创建，并分别观察收盘表现与实际模拟成交。</p><button class="secondary" @click="newJournal()">开始记录</button></div><button v-for="r in list.items" :key="r.id" class="research-journal-row" @click="openJournal(r.id)"><span><b>{{r.data.instrument.name}} · {{r.data.instrument_id}}</b><small>{{r.data.rationale}}</small><small>判断 {{dt(r.data.judgement_at)}} · 版本 {{r.version}}</small></span><span class="tag">{{r.status==='archived'?'已归档':'研究中'}}</span><ChevronRight :size="16"/></button></section>
        <section v-else class="panel research-section"><button class="text-button" @click="journal=null"><ChevronLeft :size="15"/>返回日志</button><div class="panel-heading"><div><h2>{{journal.data.instrument.name}} · 判断记录</h2><p>最新版本 {{journal.version}} · {{dt(journal.data.judgement_at)}}</p></div><div class="button-row"><button class="secondary small" @click="newJournal('','',journal)">修订判断</button><button class="text-button" @click="archive(journal)">{{journal.status==='archived'?'恢复研究':'归档'}}</button><button class="icon-button" aria-label="删除日志" @click="remove('journals',journal)"><Trash2 :size="15"/></button></div></div><div class="research-pagination"><button class="secondary small" :disabled="journal.version_page===1" @click="action(async()=>journal=await api('/me/journals/'+journal.id+'?page='+(journal.version_page-1)+'&size=20'))">较新修订</button><span>{{journal.total_versions}} 个修订 · 第 {{journal.version_page}} 页</span><button class="secondary small" :disabled="journal.version_page*20>=journal.total_versions" @click="action(async()=>journal=await api('/me/journals/'+journal.id+'?page='+(journal.version_page+1)+'&size=20'))">较早修订</button></div><article v-for="v in journal.versions" :key="v.version" class="journal-version"><h3>版本 {{v.version}} · {{dt(v.data.judgement_at)}}</h3><dl class="research-dl"><dt>判断依据</dt><dd>{{v.data.rationale}}</dd><dt>反方观点</dt><dd>{{v.data.counterargument||'未填写'}}</dd><dt>失效条件</dt><dd>{{v.data.invalidation||'未填写'}}</dd><dt>私人备注</dt><dd>{{v.data.note||'未填写'}}</dd></dl><p v-if="v.data.report_snapshot">来源报告版本 {{v.data.report_snapshot.version}} · {{v.data.report_snapshot.report_date}}</p><template v-for="c in v.calculations" :key="c.version"><p class="research-footnote">计算版本 {{c.version}} · {{dt(c.created_at)}} · 起点 {{c.data.start?.day||label(c.data.status)}} · 开盘价 {{fmt(c.data.start?.price)}}</p><div class="table-scroll"><table class="watch-table"><thead><tr><th>观察窗口</th><th>目标交易日</th><th>状态</th><th>开盘至目标收盘</th></tr></thead><tbody><tr v-for="t in c.data.targets" :key="t.horizon"><td>{{t.horizon}} 个交易日</td><td>{{t.day||'待日历覆盖'}}</td><td>{{label(t.status)}}</td><td>{{pct(t.return_pct)}}</td></tr></tbody></table></div><p>模拟成交净收益：{{c.data.simulation.realized_pnl===null?'尚无可配对的闭合成交':'¥'+fmt(c.data.simulation.realized_pnl)}} · {{label(c.data.simulation.status)}}</p></template></article></section>
      </template>

      <template v-if="view==='portfolio'">
        <!-- 组合风险：以同一虚拟账户计算仓位和行业分布，明确标记缺价和未核验数据。 -->
        <section class="panel research-section"><div class="panel-heading"><div><h2>同一账户，同一估值口径</h2><p>待成交委托不计作持仓；冻结现金已包含在现金中。</p></div><label>模拟账户<select v-model="selectedAccount" @change="refresh"><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label></div><div v-if="!accounts.length" class="research-empty"><h3>还没有模拟账户</h3><p>创建虚拟账户后，这里会显示现金与持仓的风险概况。</p><button class="secondary" @click="emit('navigate','simulation')">前往模拟交易</button></div><template v-if="risk"><p :class="['public-message',risk.quality==='incomplete'?'error':'']">{{label(risk.quality)}} · 估值 {{dt(risk.valuation_at)}} · {{risk.currency}}<br v-if="risk.quality==='incomplete'"/><span v-if="risk.quality==='incomplete'">报价缺失时不以成本补作当前市值，比例及回撤暂不提供。</span></p><div class="research-metrics"><article><small>总权益 / 持仓市值</small><strong>{{fmt(risk.equity)}} <em>/ {{fmt(risk.market_value)}}</em></strong></article><article><small>持仓 / 现金占比</small><strong>{{pct(risk.position_pct)}} <em>/ {{pct(risk.cash_pct)}}</em></strong></article><article><small>当前 / 最大回撤</small><strong>{{pct(risk.current_drawdown_pct)}} <em>/ {{pct(risk.max_drawdown_pct)}}</em></strong></article></div><div class="research-cash"><span>现金 ¥{{fmt(risk.cash)}}</span><span>已冻结 ¥{{fmt(risk.reserved_cash)}}</span><span>可用 ¥{{fmt(risk.available_cash)}}</span></div><h3>行业集中度</h3><p>最大已知行业：{{risk.top_industry||'暂无已核验分类'}} · 占持仓 {{pct(risk.industry_concentration_pct)}} · 占总权益 {{pct(risk.industry_equity_pct)}}</p><p class="research-footnote">分类覆盖 {{pct(risk.classification_coverage_pct)}} · {{risk.industry_note}}</p><div v-for="g in risk.industry_distribution" :key="g.industry" class="industry-bar"><span>{{g.industry}}</span><div><i :style="{width:(g.position_pct||0)+'%'}"></i></div><b>{{pct(g.position_pct)}}</b></div><p class="research-footnote">估值修订 {{risk.valuation_revision||'—'}} · {{risk.drawdown_basis}}</p><ResearchChart v-if="risk.curve.length>1" kind="equity" :curve="risk.curve"/><p v-if="risk.history_incomplete||risk.curve.length<=1" class="research-footnote">{{risk.history_incomplete?'历史估值存在缺口，不能据此声明完整区间回撤。':'尚无足够的历史估值点。'}}</p><details v-if="risk.history_incomplete&&risk.valid_segments?.length" class="valuation-segments"><summary>查看有效估值段（最近 {{risk.valid_segments.length}} / {{risk.segment_count}} 段）</summary><p class="research-footnote">各段分别计算，不能拼接为完整区间回撤。单个快照不提供回撤指标。</p><div class="table-scroll"><table class="watch-table"><thead><tr><th>有效快照范围</th><th>快照数</th><th>段内当前 / 最大回撤</th></tr></thead><tbody><tr v-for="(s,i) in risk.valid_segments" :key="i"><td>{{dt(s.start)}}<small>至 {{dt(s.end)}}</small></td><td>{{s.points}}</td><td>{{pct(s.current_drawdown_pct)}} / {{pct(s.max_drawdown_pct)}}</td></tr></tbody></table></div></details><div class="table-scroll"><table class="watch-table"><thead><tr><th>持仓</th><th>数量</th><th>有效市值</th><th>行业</th><th>报价 / 状态</th></tr></thead><tbody><tr v-for="p in risk.positions" :key="p.instrument_id"><td>{{p.name}}<small>{{p.instrument_id}}</small></td><td>{{p.quantity}}</td><td>{{p.quality==='valid'?fmt(p.market_value):'无法核验'}}</td><td>{{p.industry}}</td><td>{{dt(p.quote_time)}}<small>{{label(p.quality)}}</small></td></tr></tbody></table></div><p v-for="g in risk.gaps" class="warning-text">{{g.instrument_id}} · {{g.reasons.join('；')}}</p><button class="secondary" @click="askAbout('account',selectedAccount)"><MessageSquare :size="15"/>就此账户提问</button></template></section>
      </template>

      <template v-if="view==='experiments'">
        <!-- 历史实验：围绕课题保留参数、失败尝试和含费基准，并展示比较口径差异。 -->
        <section class="panel research-section"><div class="panel-heading"><div><h2>围绕一个问题，多次验证</h2><p>保留已开始的成功、失败与中断尝试，不按最高收益隐藏其他结果。</p></div><button class="primary small" :disabled="!topics.length" @click="newExperiment()"><Plus :size="15"/>新建实验</button></div><form class="research-topic-form" @submit.prevent="createTopic"><label>新课题名称<input v-model="topicName" maxlength="100" placeholder="例如：均线参数对回撤的影响" required/></label><label>研究问题<input v-model="topicQuestion" maxlength="2000" placeholder="希望证伪或验证什么？"/></label><button class="secondary small" :disabled="busy">创建课题</button></form><div class="research-filters"><label>课题<select v-model="topicFilter" @change="filter"><option value="">全部课题</option><option v-for="t in topics" :key="t.id" :value="t.id">{{t.data.name}}</option></select></label><button class="secondary" :disabled="selectedExperiments.length<2||selectedExperiments.length>5" @click="compare">比较已选 {{selectedExperiments.length}} / 5</button></div><p v-if="!list.items.length" class="research-empty">{{topics.length?'本课题尚无实验。先核对历史数据，再保存参数开始。':'创建研究课题后，即可归档独立实验。'}}</p><div v-for="r in list.items" :key="r.id" class="experiment-row"><input v-model="selectedExperiments" type="checkbox" :value="r.id" :disabled="selectedExperiments.length>=5&&!selectedExperiments.includes(r.id)" :aria-label="'选择实验'+r.id"/><button class="text-button experiment-open" @click="openExperiment(r.id)"><b>{{r.parameters.instrument_id}} · MA{{r.parameters.fast}} / MA{{r.parameters.slow}}</b><small>{{dt(r.created_at)}} · {{r.started_at?'课题尝试 #'+r.attempt_no:'尚未开始，不计尝试'}} · {{r.result?.validated?'证据完整':'待核验或未验证'}}</small></button><span class="tag">{{label(r.status)}}</span><b>{{pct(r.result?.summary?.return_pct)}}</b><button v-if="['queued','running'].includes(r.status)" class="text-button" @click="action(async()=>{await post('/me/experiments/'+r.id+'/stop');await refresh()})">停止</button><button v-else class="text-button" @click="newExperiment(r)">重新运行</button></div></section>
        <section v-if="comparison" class="panel research-section"><div class="panel-heading"><h2>实验比较</h2><button class="text-button" @click="comparison=null">收起</button></div><p v-for="n in comparison.comparability" class="warning-text">{{n.field}} · {{n.reason}}</p><div class="table-scroll"><table class="watch-table"><thead><tr><th>参数 / 状态</th><th>初始资金</th><th>区间收益</th><th>最大回撤</th><th>交易数</th></tr></thead><tbody><tr v-for="r in comparison.items" :key="r.id"><td>MA{{r.parameters.fast}} / MA{{r.parameters.slow}} · {{label(r.status)}}</td><td>{{fmt(r.parameters.initial_cash)}}</td><td>{{pct(r.result?.summary?.return_pct)}}</td><td>{{pct(r.result?.summary?.max_drawdown_pct)}}</td><td>{{r.result?.summary?.round_trips??'—'}}</td></tr></tbody></table></div><div class="table-scroll"><table class="watch-table"><thead><tr><th>冻结口径</th><th v-for="r in comparison.items" :key="r.id">{{r.parameters.instrument_id}} · #{{r.attempt_no??'未开始'}}</th></tr></thead><tbody><tr><td>快 / 慢线、止损、样本内比例</td><td v-for="r in comparison.items">{{r.parameters.fast}} / {{r.parameters.slow}} · {{pct(r.parameters.stop_loss_pct*100)}} · {{pct(r.parameters.train_ratio*100)}}</td></tr><tr><td>严格核验 / 策略版本</td><td v-for="r in comparison.items">{{r.result?.validated?'证据完整':'未验证或无结果'}} · {{r.result?.strategy_version||'未知'}}</td></tr><tr><td>样本内收益 / 样本外收益</td><td v-for="r in comparison.items">{{pct(r.result?.in_sample?.metrics.return_pct)}} / {{pct(r.result?.out_of_sample?.metrics.return_pct)}}</td></tr><tr><td>单只含费预算 / 累计费用</td><td v-for="r in comparison.items">{{fmt(r.result?.budget_snapshot)}} / {{fmt(r.result?.summary?.fees)}}</td></tr><tr><td>数据区间</td><td v-for="r in comparison.items">{{safeFacts(r.result?.data_range||'尚无结果')}}</td></tr><tr><td>数据哈希</td><td v-for="r in comparison.items" class="snapshot-id">{{r.result?.data_hash||'未生成'}}</td></tr></tbody></table></div><p class="research-footnote">比较保留失败实验；费用、资金、区间或验证状态不一致时提示差异，不生成胜出排名。</p></section>
        <section v-if="experiment" class="panel research-section"><div class="panel-heading"><div><h2>{{experiment.parameters.instrument_id}} · 实验档案</h2><p>{{label(experiment.status)}} · {{experiment.started_at?'尝试 #'+experiment.attempt_no:'尚未开始'}}</p></div><button class="text-button" @click="experiment=null">收起</button></div><p v-if="experiment.error_code" class="warning-text">{{label(experiment.error_code)}}</p><template v-if="experiment.result"><p v-for="w in experiment.result.warnings" class="warning-text">{{w}}</p><div class="research-metrics"><article><small>策略全区间收益</small><strong>{{pct(experiment.result.summary.return_pct)}}</strong></article><article><small>最大回撤</small><strong>{{pct(experiment.result.summary.max_drawdown_pct)}}</strong></article><article><small>买入持有基准</small><strong>{{pct(experiment.result.benchmarks?.buy_hold.full.metrics.return_pct)}}</strong></article></div><BenchmarkChart v-if="experiment.result.benchmarks" :result="experiment.result"/><ResearchChart v-else kind="equity" :curve="experiment.result.full.equity"/><div class="table-scroll"><table class="watch-table"><thead><tr><th>独立区间</th><th>策略收益</th><th>买入持有收益</th><th>基准剩余现金</th></tr></thead><tbody><tr v-for="part in ['full','in_sample','out_of_sample']" :key="part"><td>{{{full:'全区间',in_sample:'样本内',out_of_sample:'样本外'}[part]}}</td><td>{{pct(experiment.result[part].metrics.return_pct)}}</td><td>{{pct(experiment.result.benchmarks?.buy_hold[part].metrics.return_pct)}}</td><td>{{fmt(experiment.result.benchmarks?.buy_hold[part].metrics.remaining_cash)}}</td></tr></tbody></table></div><p class="research-footnote">{{experiment.result.benchmarks?.buy_hold.full.execution}}</p><p class="research-footnote">{{experiment.result.benchmarks?.buy_hold.subperiod_basis}}</p><p v-if="experiment.result.benchmarks?.index.status==='available'">{{experiment.result.benchmarks.index.name}} · {{experiment.result.benchmarks.index.basis}}</p><p v-else class="research-footnote">未选择可用指数观察基准。</p><details><summary>查看冻结参数与可复核成交</summary><pre class="research-json">{{safeFacts(experiment.parameters)}}</pre><div class="table-scroll"><table class="watch-table"><thead><tr><th>成交时间</th><th>方向</th><th>价格</th><th>数量</th><th>费用</th></tr></thead><tbody><tr v-for="(t,i) in experiment.result.full.trades" :key="i"><td>{{dt(t.ts)}}</td><td>{{t.side==='buy'?'买入':'卖出'}}</td><td>{{fmt(t.price)}}</td><td>{{t.quantity}}</td><td>{{fmt(t.fees)}}</td></tr></tbody></table></div></details><p class="snapshot-id">数据 {{experiment.result.data_hash}} · {{experiment.result.strategy_version}}</p><div class="button-row"><button class="secondary small" @click="action(async()=>{const r=await post('/me/backtests/'+experiment.result_id+'/reproduce');notice=r.identical?'按冻结快照复算一致。':'复算结果存在差异，请检查执行环境。'})">按冻结快照复算</button><button class="secondary small" @click="askAbout('experiment',experiment.id)">就此实验提问</button><button class="text-button" @click="newExperiment(experiment)">作为新尝试再运行</button></div></template></section>
      </template>

      <template v-if="view==='assistant'">
        <!-- 项目助手：以纯文本和来源事实卡显示已校验回答，保留停止及会话续读入口。 -->
        <div class="assistant-layout"><aside v-show="!assistantPanel||showHistory" class="panel assistant-sessions"><div class="panel-heading"><h2>我的对话</h2><button class="icon-button" aria-label="新建对话" :disabled="busy" @click="newSession"><Plus :size="18"/></button></div><form @submit.prevent="refresh"><label class="sr-only" for="session-search">搜索对话</label><input id="session-search" v-model="query" placeholder="搜索会话"/></form><button v-for="s in sessions.items" :key="s.id" :class="['assistant-session',{active:session?.id===s.id}]" @click="action(async()=>chooseSession(s.id))"><MessageSquare :size="14"/><span>{{s.data.title}}<small>{{dt(s.updated_at)}}</small></span></button><p v-if="!sessions.items.length" class="research-footnote">还没有会话，输入问题即可开始。</p><div class="button-row"><button class="icon-button" aria-label="上一页对话" :disabled="sessionPage===1" @click="sessionPage--;refresh()"><ChevronLeft :size="15"/></button><small>{{sessionPage}} / {{Math.max(1,Math.ceil(sessions.total/size))}}</small><button class="icon-button" aria-label="下一页对话" :disabled="sessionPage*size>=sessions.total" @click="sessionPage++;refresh()"><ChevronRight :size="15"/></button></div><button v-if="session" class="text-button danger-text" @click="remove('assistant/sessions',session)"><Trash2 :size="13"/>删除当前对话</button></aside>
          <section class="panel assistant-conversation"><div class="assistant-scope"><ShieldCheck :size="17"/><p>可以聊天，也可以直接查询本人的研究结果，无需附带资料。配置变更先展示，手动应用后生效；添加股票需核对确认。删除与已有数据修改请在对应页面手动操作。</p></div><details class="assistant-help-index"><summary>查看已实现功能的项目帮助（不调用模型）</summary><div class="assistant-help-links"><button v-for="e in help?.entries" :key="e.id" class="text-button" @click="notice=e.title+'：'+e.text">{{e.title}}</button></div></details><div class="assistant-messages" aria-live="polite"><div v-if="!session?.messages.length" class="assistant-welcome"><span class="assistant-orb"><MessageSquare :size="27"/></span><h2>聊聊，或让助手帮你查</h2><p>直接说“分析最近的报告”“把预算调整为五百元”或“添加贵州茅台到自选”。</p><div class="assistant-starters"><button @click="question='帮我分析最近的研究报告'">分析最近的报告</button><button @click="question='把单只证券预算调整为五百元'">调整研究预算</button><button @click="question='我们聊聊吧'">随便聊聊</button></div><small>没有可用模型时，仅提供明确标注的项目帮助资料。</small></div><article v-for="m in session?.messages" :key="m.id" class="assistant-turn"><div class="assistant-question"><strong>我</strong><p>{{m.question}}</p><small>{{dt(m.created_at)}}</small></div><div class="assistant-answer"><div class="assistant-answer-heading"><MessageSquare :size="15"/><b>项目助手</b><span class="tag">{{label(m.status)}}</span><span v-if="m.reply?.source==='project_help'" class="tag">静态帮助，未调用模型</span></div><p v-if="m.reply?.answer" class="assistant-prose">{{m.reply.answer}}</p><p v-else-if="['queued','running','validating'].includes(m.status)" class="muted"><LoaderCircle :size="14" class="spin"/>{{m.status==='queued'?'在个人队列中等待':'正在按需查询资料并生成、校验回答。'}}<button class="text-button" @click="stopMessage(m)"><Square :size="12"/>停止</button></p><p v-else class="warning-text">{{label(m.error_code||m.status)}}{{m.status==='uncertain'?'。可能已消耗额度；重新生成将发起一次新请求。':''}}</p><AssistantAction v-for="(a,i) in m.reply?.actions" :key="i" :action="a" :disabled="busy" @apply="applyAssistantAction(m,Number(i))"/><p v-for="note in m.reply?.important_notes" class="research-footnote">{{note}}</p><p v-if="m.reply?.omitted_turns" class="research-footnote">为遵守上下文预算或当前授权，已省略 {{m.reply.omitted_turns}} 轮历史。</p><details v-for="r in m.reply?.references" :key="r.id" class="assistant-source"><summary><span>{{r.title||r.id}}</span><small>{{r.version?'版本 '+r.version:''}} {{r.data_time?dt(r.data_time):''}}</small></summary><p v-if="r.source_deleted" class="warning-text">原始来源已删除；旧回答不能用于重新发送其已删除事实。</p><SourceFacts v-else-if="r.facts" :source="r"/><a class="text-button" :href="r.href" @click.prevent="sourceLink(r)">打开来源</a></details><button v-if="!['queued','running','validating'].includes(m.status)&&!pending" class="text-button small" :disabled="busy" @click="send(m)"><RefreshCw :size="12"/>重新生成（新请求）</button></div></article><div v-if="session?.total>size" class="research-pagination"><button class="secondary small" :disabled="messagePage*size>=session.total" @click="messagePage++;action(async()=>openSession(session.id))">更早消息</button><span>第 {{messagePage}} 页 / {{session.total}} 条</span><button class="secondary small" :disabled="messagePage===1" @click="messagePage--;action(async()=>openSession(session.id))">较新消息</button></div></div>
          <form class="assistant-compose" @submit.prevent="send()"><div class="assistant-compose-controls"><label>个人模型<select v-model="profileId"><option value="">使用本人默认配置</option><option v-for="p in profiles.filter(p=>p.active)" :key="p.id" :value="p.id">{{p.name}} · {{p.model}}</option></select></label><button type="button" class="text-button" @click="emit('navigate','models')">配置与授权</button></div><p class="assistant-query-note">按需查询资料；查询与回答的模型调用分别计入用量。问题与必要历史会发送至所选模型。</p><p class="assistant-model-summary">当前模型：{{selectedProfile?selectedProfile.name+' · '+selectedProfile.model:'尚未选择可用配置，可先查看项目帮助'}}</p><details class="assistant-optional-context"><summary>指定研究资料（可选）</summary><div class="assistant-context-picker"><label><span class="sr-only">资料类型</span><select v-model="contextKind" @change="contextId=''"><option v-for="(v,k) in kindLabels" :key="k" :value="k">{{v}}</option></select></label><label class="context-object"><span class="sr-only">明确选择研究对象</span><select v-model="contextId"><option value="">选择本人资料或共享证券</option><option v-for="c in contextOptions" :key="c.id" :value="c.id">{{c.title}}</option></select></label><button type="button" class="secondary small" :disabled="!contextId||contexts.length>=5" @click="addContext">指定</button></div></details><div v-if="contexts.length" class="context-chips"><button v-for="(c,i) in contexts" :key="c.kind+c.id" type="button" @click="contexts.splice(i,1)" :aria-label="'移除资料'+c.id">{{kindLabels[c.kind]}} · {{contextTitle(c)}} ×</button></div><label class="sr-only" for="assistant-question">项目问题</label><textarea id="assistant-question" v-model="question" rows="3" placeholder="聊聊、查询研究结果，或说出想调整的项目配置。无需附带分析结果。" :disabled="!!pending" @keydown.ctrl.enter.prevent="send()"/><div class="assistant-compose-footer"><small :class="{'warning-text':Array.from(question).length>4000}">{{Array.from(question).length}} / 4000 字符 · Ctrl + Enter 发送</small><button v-if="pending" type="button" class="secondary" :disabled="busy" @click="stopMessage(pending)"><Square :size="13"/>停止生成</button><button v-else class="primary" :disabled="busy||!question.trim()||Array.from(question).length>4000"><Send :size="15"/>发送</button></div></form></section></div>
      </template>

      <div v-if="['readiness','alerts','journals','experiments'].includes(view)" class="research-pagination"><label>每页<select v-model.number="size" @change="filter"><option :value="20">20</option><option :value="50">50</option></select></label><span>共 {{view==='readiness'?readiness?.total||0:list.total}} 条 · 第 {{page}} 页</span><button class="secondary small" :disabled="page===1||loading" @click="changePage(-1)"><ChevronLeft :size="14"/>上一页</button><button class="secondary small" :disabled="page*size>=(view==='readiness'?readiness?.total||0:list.total)||loading" @click="changePage(1)">下一页<ChevronRight :size="14"/></button></div>
    </main>
    <div v-if="editor&&editorOpen" class="modal-scrim research-modal-scrim"><form class="modal research-editor" ref="editorForm" role="dialog" aria-modal="true" aria-label="研究记录编辑" @keydown.tab="trap" @keydown.esc.prevent="editorOpen=false" @submit.prevent="editor.kind==='alert'?saveAlert():editor.kind==='journal'?saveJournal():saveExperiment()"><div class="panel-heading"><h2>{{editor.kind==='alert'?'设置条件提醒':editor.kind==='journal'?(editor.id?'修订研究判断':'记录研究判断'):'保存独立实验'}}</h2><div class="button-row"><button type="button" class="text-button" @click="editorOpen=false">保留草稿收起</button><button type="button" class="text-button" @click="confirm('放弃这份尚未保存的草稿？').then(v=>{if(v)editor=null})">放弃</button></div></div><p v-if="error" class="public-message error" role="alert">{{error}}</p>
      <template v-if="editor.kind==='alert'"><div class="form-grid"><label>名称<input v-model="editor.data.name" required maxlength="100"/></label><label>证券<select v-model="editor.data.instrument_id" required><option v-for="w in watchlist" :key="w.id" :value="w.id">{{w.name}} · {{w.id}}</option></select></label><label>触发条件<select v-model="editor.data.condition"><option v-for="(v,k) in conditionLabels" :key="k" :value="k">{{v}}</option></select></label><label v-if="!['risk_changed','candidate_invalid'].includes(editor.data.condition)">阈值{{editor.data.condition.startsWith('change_')?'（%）':'（报价币种）'}}<input v-model.number="editor.data.threshold" type="number" step="any" required/></label><label v-if="editor.data.condition==='candidate_invalid'">明确选择来源报告<select v-model="editor.data.report_id" required><option :value="null">请选择</option><option v-for="r in reports" :key="r.id" :value="r.id">{{r.report_date}} · 版本 {{r.version}}</option></select></label><label>冷却分钟数<input v-model.number="editor.data.cooldown_minutes" type="number" min="0" max="525600" required/></label><label>有效期<select :value="editor.data.expires_at?'30':'continuous'" @change="editor.data.expires_at=($event.target as HTMLSelectElement).value==='continuous'?null:new Date(Date.now()+30*86400000).toISOString()"><option value="30">30 天</option><option value="continuous">持续有效，直至停用</option></select></label><label v-if="editor.data.expires_at">到期时间（上海）<input type="datetime-local" :value="shanghaiDateTime(editor.data.expires_at)" required @change="editor.data.expires_at=($event.target as HTMLInputElement).value?new Date(($event.target as HTMLInputElement).value+'+08:00').toISOString():null"/><button type="button" class="text-button" @click="editor.data.expires_at=new Date(Date.now()+30*86400000).toISOString()">从现在延长30天</button></label><label>免打扰开始<input v-model="editor.data.dnd_start" type="time"/></label><label>免打扰结束<input v-model="editor.data.dnd_end" type="time"/></label><label class="check-label"><input v-model="editor.data.email" type="checkbox"/>此规则允许邮件提醒</label><label class="check-label"><input v-model="editor.data.enabled" type="checkbox"/>启用规则</label></div><p v-if="editor.reference" class="research-footnote">已冻结参考收盘：{{fmt(editor.reference.close)}} · {{dt(editor.reference.ts)}}。编辑阈值或启停沿用这一基准。</p><p class="research-footnote">涨跌幅会冻结创建时已核验的参考收盘价。免打扰期间暂存，结束后仅合并仍有效的事件。</p><p v-if="notice" class="public-message">{{notice}}</p><div class="form-actions"><button type="button" class="secondary" :disabled="busy" @click="saveAlert(true)">预览条件，不保存</button><button class="primary" :disabled="busy">保存提醒</button></div></template>
      <template v-else-if="editor.kind==='journal'"><div class="form-grid"><label>证券<select v-model="editor.data.instrument_id" required><option v-for="w in watchlist" :key="w.id" :value="w.id">{{w.name}} · {{w.id}}</option></select></label><label>来源报告（可选）<select v-model="editor.data.report_id"><option :value="null">直接从证券记录</option><option v-for="r in reports" :key="r.id" :value="r.id">{{r.report_date}} · 版本 {{r.version}}</option></select></label><label class="span-two">判断依据<textarea v-model="editor.data.rationale" required maxlength="4000" rows="3"/></label><label class="span-two">反方观点<textarea v-model="editor.data.counterargument" maxlength="4000" rows="2"/></label><label class="span-two">失效条件<textarea v-model="editor.data.invalidation" maxlength="4000" rows="2"/></label><label class="span-two">私人备注<textarea v-model="editor.data.note" maxlength="4000" rows="2"/></label><label class="span-two">关联本人模拟成交标识（逗号分隔，可选）<input :value="editor.data.order_ids.join(',')" @input="editor.data.order_ids=($event.target as HTMLInputElement).value.split(',').map((s:string)=>s.trim()).filter(Boolean)" placeholder="从模拟成交记录复制标识"/></label></div><p class="research-footnote">观察起点为判断时点之后首次已核验开盘；基准日计第 1 日，观察第 1 / 5 / 20 个交易日收盘。缺失目标不会跳到别的日期。</p><div class="form-actions"><button class="primary" :disabled="busy">保存判断版本</button></div></template>
      <template v-else><div class="form-grid"><label>研究课题<select v-model="editor.topic_id" required><option v-for="t in topics" :key="t.id" :value="t.id">{{t.data.name}}</option></select></label><label>证券<select v-model="editor.parameters.instrument_id" required><option v-for="w in watchlist.filter(w=>['SH','SZ'].includes(w.market)&&['stock','etf'].includes(w.asset_class))" :key="w.id" :value="w.id">{{w.name}} · {{w.id}}</option></select></label><label>初始虚拟资金<input v-model.number="editor.parameters.initial_cash" type="number" min="1" max="100000000" required/></label><label>快线<input v-model.number="editor.parameters.fast" type="number" min="2" max="120" required/></label><label>慢线<input v-model.number="editor.parameters.slow" type="number" min="3" max="250" required/></label><label>样本内占比<input v-model.number="editor.parameters.train_ratio" type="number" min="0.5" max="0.9" step="0.05" required/></label><label>止损比例<input v-model.number="editor.parameters.stop_loss_pct" type="number" min="0.01" max="0.5" step="0.01" required/></label><label>指数观察基准（可选）<select v-model="editor.index_id"><option :value="null">不选择</option><option v-for="w in watchlist.filter(w=>w.asset_class==='index')" :key="w.id" :value="w.id">{{w.name}} · {{w.id}}</option></select></label><label>开始日期<input v-model="editor.parameters.start_date" type="date"/></label><label>结束日期<input v-model="editor.parameters.end_date" type="date"/></label><label class="check-label span-two"><input v-model="editor.parameters.strict" type="checkbox"/>严格核验历史交易状态与公司行动</label></div><p class="research-footnote">买入持有基准使用首个可执行开盘、相同预算和费用。样本内外独立重置资金，不拼接曲线。</p><div class="form-actions"><button class="primary" :disabled="busy">保存参数并加入队列</button></div></template>
    </form></div>
    <ConfirmDialog :message="confirmText" @choose="settle"/>
    <div v-if="leavePrompt" class="modal-scrim"><section class="modal research-leave" ref="leaveForm" @keydown.tab="trap" role="dialog" aria-modal="true" aria-labelledby="draft-title"><h2 id="draft-title">当前有尚未保存的草稿</h2><p>可将草稿留在本次登录中，返回时继续编辑。退出登录或刷新页面会清除未保存草稿。</p><div class="button-row"><button class="secondary" @click="leave(false)">放弃草稿并离开</button><button class="primary" @click="leave(true)">保留草稿并离开</button></div></section></div>
  </div>
</template>
